import json, sys
data = json.load(sys.stdin)
json.dump(data, open('after-cpm-packages.json','w'), indent=2)

# Compare with baseline
baseline = json.load(open('baseline-packages.json'))

def get_packages(d):
    pkgs = {}
    for proj in d['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            tf = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tf, pkg['id'])
                pkgs[key] = pkg['resolvedVersion']
    return pkgs

b = get_packages(baseline)
a = get_packages(data)

changes = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        changes.append((k[0], k[1], k[2], bv, av))

if changes:
    print('CHANGES:')
    for c in changes:
        print(f'  {c[0]:20} {c[1]:12} {c[2]:50} {c[3]} -> {c[4]}')
else:
    print('No changes - fully version-neutral')
print(f'\nTotal packages: baseline={len(b)}, after={len(a)}')
"

